<script setup lang="ts">
import { useLedgerI18n } from '../i18n'
import { computed, ref } from 'vue'
import { chartData } from '../charts'
import { money } from '../model'
import type { LedgerDay } from '../types'
const { text } = useLedgerI18n()
const props = defineProps<{ days: LedgerDay[]; start: string; end: string }>()
const mode = ref<'income' | 'expense'>('income'), detail = ref<{ date: string; amount: number; submitted: boolean }>()
const colors = ['#2f9868', '#83b99b', '#c39c57', '#7baeb9', '#a891b8', '#9fae5a', '#d39279']
const data = computed(() => chartData(props.days, props.start, props.end, mode.value, text))
const rings = computed(() => { const positive = data.value.categories.filter(c => c.amount > 0), total = positive.reduce((sum, c) => sum + c.amount, 0); let offset = 0; return positive.map((c, i) => { const result = { ...c, length: c.amount / total * 100, offset, color: colors[i % colors.length] }; offset += result.length; return result }) })
const groups = computed(() => [{ name: text("每日对比"), items: data.value.daily }, { name: text("月度对比"), items: data.value.monthly }].map(group => ({ ...group, max: Math.max(1, ...group.items.map(p => Math.abs(p.amount))) })))
</script>
<template>
  <section class="history-analytics" :aria-label="text('收支统计图')">
    <div class="analytics-hero"><div class="analytics-toolbar"><span>{{ start }} {{ text('至') }} {{ end }}</span><div class="analytics-tabs"><button :aria-pressed="mode === 'income'" @click="mode = 'income'">{{ text('收入') }}</button><button :aria-pressed="mode === 'expense'" @click="mode = 'expense'">{{ text('支出') }}</button></div></div><p>{{ mode === 'income' ? text("营业总收入") : text("共支出") }}</p><strong>${{ money(data.total) }}</strong><small>{{ text('指定班次已提交 {count} 天 · 仅统计已提交账目', { count: data.submittedDays }) }}</small></div>
    <div class="analytics-body"><h2>{{ mode === 'income' ? text("收入构成") : text("支出构成") }}</h2><div class="composition-layout"><svg viewBox="0 0 128 128" role="img" :aria-label="mode === 'income' ? text('收入分类占比') : text('支出分类占比')"><circle cx="64" cy="64" r="48" fill="none" stroke="#edf1e9" stroke-width="19" /><g transform="rotate(-90 64 64)"><circle v-for="ring in rings" :key="ring.id" cx="64" cy="64" r="48" fill="none" :stroke="ring.color" stroke-width="19" pathLength="100" :stroke-dasharray="`${ring.length} ${100 - ring.length}`" :stroke-dashoffset="-ring.offset" /></g><text x="64" y="61" text-anchor="middle">{{ mode === 'income' ? text("收入构成") : text("支出构成") }}</text><text x="64" y="76" text-anchor="middle">{{ text('{count} 个项目', { count: rings.length }) }}</text></svg><div class="composition-list"><div v-for="(category, i) in data.categories" :key="category.id"><span class="category-dot" :style="{ background: colors[i % colors.length] }"></span><span class="category-name">{{ category.name }}<small>{{ category.amount < 0 ? text("负数调整") : data.total ? (category.amount / data.total * 100).toFixed(1) + '%' : '0%' }}</small><i :style="{ width: `${data.total ? Math.max(0, Math.min(100, category.amount / data.total * 100)) : 0}%`, background: colors[i % colors.length] }"></i></span><strong>${{ money(category.amount) }}</strong></div><p v-if="!data.categories.length" class="muted small">{{ text('暂无已提交金额') }}</p></div></div>
    <div v-for="group in groups" :key="group.name" class="analytics-trend"><h2>{{ group.name }}</h2><div class="trend-scale"><span>{{ money(group.max) }}</span><span>{{ money(group.max / 2) }}</span><span>0.00</span></div><div class="trend-scroll"><div class="trend-bars" :style="{ '--count': group.items.length }"><div v-for="point in group.items" :key="point.date" class="trend-column"><button class="trend-bar" :class="{ negative: point.amount < 0 }" :aria-label="`${point.date} · ${point.submitted ? money(point.amount) : text('未提交')}`" @click="detail = point"><span class="trend-fill" :style="{ height: `${Math.max(1, Math.abs(point.amount) / group.max * 100)}%`, bottom: '0', background: point.amount < 0 ? '#b05c48' : point.submitted ? undefined : '#dbe2d9' }"></span></button><small>{{ point.date.slice(5) || point.date }}</small></div></div></div></div><p class="trend-detail" role="status">{{ detail ? `${detail.date} · ${detail.submitted ? money(detail.amount) : text('未提交，不计入统计')}` : text('点击柱条查看日期和金额') }}</p><p class="analytics-note">{{ text('负数仍计入总额，环形图只显示正数构成。现金收入包含已付现金开支，底钱与抽款不重复计入收入。') }}</p></div>
  </section>
</template>
